export function groupDigits(digits, country) {
    const patterns = GROUP_PATTERNS[country];
    if (!patterns)
        return digits;
    // Find a pattern whose total length matches the input
    const matched = patterns.find((p) => p.reduce((a, b) => a + b, 0) === digits.length);
    if (!matched)
        return digits; // no match → no dashes
    const groups = [];
    let pos = 0;
    for (const size of matched) {
        groups.push(digits.slice(pos, pos + size));
        pos += size;
    }
    return groups.join(" ");
}