export function isValidDateString(value) {
    if (!value)
        return false;
    const parts = value.includes(",")
        ? value.split(",").map((s) => s.trim())
        : value.includes("-")
            ? value.split("-").map((s) => s.trim())
            : [value];
    return parts.every((p) => !isNaN(new Date(p).getTime()));
}
export function isValidSingleDate(v) {
    return !isNaN(new Date(v).getTime());
}
export function getValidMultipleDate(raw) {
    if (!raw)
        return [];
    return raw
        ?.split(",")
        ?.map((s) => s.trim())
        ?.filter(isValidSingleDate);
}
export function removeWeekend(dates) {
    return dates.filter((d) => {
        const dd = new Date(d);
        const day = dd.getDay();
        return day !== 0 && day !== 6;
    });
}
export function isWeekend(dateToCheck) {
    const day = dateToCheck.getDay();
    return day === 0 || day === 6;
}